BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || v.patch
FROM (VALUES
  ('g-kentei-b-q20', '{"calc": "全データ10件を、2件ずつのミニバッチ5組に分ける場合で考える。\n\n全データ一括で1歩ずつ進む方法なら:\n  10件ぜんぶの誤差を計算 → それでようやく重みを1回更新\n  → 1エポック(全データを1周)の間に、重みの更新は1回だけ\n\nミニバッチ(SGD、2件ずつ)なら:\n  2件の誤差を計算 → 重みを更新、を5回繰り返す\n  → 同じ1エポックの間に、重みの更新が5回できる\n\n1回あたりの計算は軽いのに、同じデータ量で5倍の回数「坂を下る」動きができる。これが小分けにする効果。"}'::jsonb),
  ('g-kentei-b-q24', '{"vs": "畳み込み層は画像の局所特徴を拾う、全結合層は全部の入力をまとめてつなぐ、プーリング層は特徴を粗くまとめて縮める。どれも順番を持ち越して系列を処理する層ではない。なお「回帰」という名前から、統計の回帰分析(数値を予測する手法)や「時間をさかのぼって処理する」ことを連想して戸惑いやすいが、ここでの「回帰」はそのどちらとも違う。recurrent＝ぐるっと同じ場所へ戻ってくる、という意味で、自分の出力が輪を描くように自分自身の入力へ戻ってくる(ループする)ことを指す。処理そのものは常に先頭から後ろへ、時間が進む向きにしか進まない。ただそのつど「1つ前の時点の出力」を次の時点の入力に持ち越しているだけで、過去へさかのぼって計算し直しているわけではない。"}'::jsonb),
  ('g-kentei-b-q25', '{"terms": [["深いネットワーク（層が深い）", "入力から出力までの間に、変換を行う層(レイヤー)がたくさん積み重なっていること。層を1つ通るたびに特徴が少しずつ組み合わさり複雑になるが、学習の「直してね」の合図(勾配)も、層を通るたびに薄まりながら奥まで届かなければならなくなる"], ["残差接続（スキップ結合）", "層を飛び越えて入力を先の層へ足す近道。深いネットワークの学習を可能にした"], ["ResNet（Residual Network）", "residual＝残差。学ぶのを「差分だけ」にして深い層を可能にした。残差接続を使い、100層を超える深さでも学習できるようにした画像認識モデル"]]}'::jsonb),
  ('g-kentei-b-q29', '{"terms": [["GRU（Gated Recurrent Unit）", "直訳は「ゲート付きの再帰ユニット」。LSTMより門(ゲート)を減らして簡単にした、系列を扱う手法。計算が軽い"], ["ゲート（門）", "情報をどれだけ通す・忘れるかを0〜1の割合で調整する「弁」のようなもの。LSTMは入力・忘却・出力の3種、GRUはこれを更新・リセットの2種にまとめて減らしている"], ["LSTM（Long Short-Term Memory）", "直訳は「長い・短い期間の記憶」。門と記憶で長い系列の情報を保つ、RNNの改良版"]], "viz": "<svg viewBox=\"0 0 340 135\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">門（ゲート）の数を減らして軽くする</text><text x=\"80\" y=\"30\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">LSTM（門3つ）</text><rect x=\"15\" y=\"40\" width=\"130\" height=\"66\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\"/><circle cx=\"50\" cy=\"60\" r=\"8\" fill=\"#3b82f6\" opacity=\"0.8\"/><text x=\"50\" y=\"76\" fill=\"#e8eaf0\" font-size=\"7\" text-anchor=\"middle\">入力</text><circle cx=\"80\" cy=\"72\" r=\"8\" fill=\"#3b82f6\" opacity=\"0.8\"/><text x=\"80\" y=\"88\" fill=\"#e8eaf0\" font-size=\"7\" text-anchor=\"middle\">忘却</text><circle cx=\"110\" cy=\"60\" r=\"8\" fill=\"#3b82f6\" opacity=\"0.8\"/><text x=\"110\" y=\"76\" fill=\"#e8eaf0\" font-size=\"7\" text-anchor=\"middle\">出力</text><text x=\"80\" y=\"100\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">3つの門を管理</text><text x=\"255\" y=\"30\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">GRU（門2つ）</text><rect x=\"195\" y=\"40\" width=\"130\" height=\"66\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\"/><circle cx=\"235\" cy=\"66\" r=\"8\" fill=\"#6ab08d\" opacity=\"0.85\"/><text x=\"235\" y=\"82\" fill=\"#e8eaf0\" font-size=\"7\" text-anchor=\"middle\">更新</text><circle cx=\"285\" cy=\"66\" r=\"8\" fill=\"#6ab08d\" opacity=\"0.85\"/><text x=\"285\" y=\"82\" fill=\"#e8eaf0\" font-size=\"7\" text-anchor=\"middle\">リセット</text><text x=\"260\" y=\"100\" fill=\"#6ab08d\" font-size=\"7.5\" text-anchor=\"middle\">2つの門だけで済ませる</text><text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">門(ゲート)＝情報をどれだけ通すか0〜1で決める弁。数が少ないほど計算が軽い</text></svg>"}'::jsonb),
  ('g-kentei-b-q48', '{"vs": "敵対的サンプルは使うとき(推論時)の入力を細工する攻撃、ディープフェイクは本物そっくりの偽コンテンツを作る技術、フィルターバブルは好みの情報に囲まれる現象。どれも学習データを汚す攻撃ではない。見分けるコツは「いつ仕掛けるか」の一点に絞ること。学習データそのものに毒を仕込むのがデータポイズニング、学習が終わったあと使う瞬間の入力にノイズを仕込むのが敵対的サンプル。狙うタイミングが訓練フェーズか推論フェーズかで、必ずどちらか一方に決まる。", "viz": "<svg viewBox=\"0 0 340 115\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">どの段階を狙う攻撃か</text><line x1=\"30\" y1=\"60\" x2=\"310\" y2=\"60\" stroke=\"#2a2f3f\" stroke-width=\"1.6\"/><circle cx=\"90\" cy=\"60\" r=\"4\" fill=\"#8892a4\"/><circle cx=\"250\" cy=\"60\" r=\"4\" fill=\"#8892a4\"/><text x=\"90\" y=\"45\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">学習（訓練）</text><text x=\"250\" y=\"45\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">推論（使うとき）</text><line x1=\"90\" y1=\"64\" x2=\"90\" y2=\"85\" stroke=\"#c47070\" stroke-width=\"1.4\"/><text x=\"90\" y=\"98\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">データポイズニング</text><text x=\"90\" y=\"109\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">訓練データに毒を混ぜる</text><line x1=\"250\" y1=\"64\" x2=\"250\" y2=\"85\" stroke=\"#e3b341\" stroke-width=\"1.4\"/><text x=\"250\" y=\"98\" fill=\"#e3b341\" font-size=\"8.5\" text-anchor=\"middle\">敵対的サンプル</text><text x=\"250\" y=\"109\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">入力に小さなノイズを混ぜる</text></svg>"}'::jsonb),
  ('g-kentei-b-q5', '{"kid": "ここでの「近い」「遠い」は道のりの物理的な距離ではなく、出発点から何回ノード(節点)をたどればそこに着くかという“手数”のこと。出発点から近い場所(1手で着く場所)を全部調べ、次に一歩遠い場所(2手で着く場所)を全部調べる…と、輪を広げるように浅い方から探すやり方。", "terms": [["幅優先探索", "出発点に近い順に、同じ深さの節点を全部調べてから次の深さへ進む方法"], ["深さ優先探索", "一本道をとことん奥まで進み、行き止まったら戻る逆の方法"], ["近い・遠い（探索の意味）", "物理的な距離ではなく、出発点から何回たどればそこに着くかという「手数(ホップ数)」のこと。1手で着く場所が一番近く、2手・3手…と手数が増えるほど遠い"]], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">近い順（同じ手数を全部）に調べる</text><circle cx=\"170\" cy=\"35\" r=\"12\" fill=\"#3b82f6\"/><text x=\"170\" y=\"39\" fill=\"#0b0f1a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">1</text><line x1=\"170\" y1=\"47\" x2=\"100\" y2=\"70\" stroke=\"#8892a4\"/><line x1=\"170\" y1=\"47\" x2=\"170\" y2=\"70\" stroke=\"#8892a4\"/><line x1=\"170\" y1=\"47\" x2=\"240\" y2=\"70\" stroke=\"#8892a4\"/><circle cx=\"100\" cy=\"80\" r=\"12\" fill=\"#60a5fa\"/><text x=\"100\" y=\"84\" fill=\"#0b0f1a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">2</text><circle cx=\"170\" cy=\"80\" r=\"12\" fill=\"#60a5fa\"/><text x=\"170\" y=\"84\" fill=\"#0b0f1a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">3</text><circle cx=\"240\" cy=\"80\" r=\"12\" fill=\"#60a5fa\"/><text x=\"240\" y=\"84\" fill=\"#0b0f1a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">4</text><line x1=\"100\" y1=\"92\" x2=\"70\" y2=\"113\" stroke=\"#8892a4\"/><line x1=\"100\" y1=\"92\" x2=\"130\" y2=\"113\" stroke=\"#8892a4\"/><circle cx=\"70\" cy=\"122\" r=\"11\" fill=\"#6ab08d\"/><text x=\"70\" y=\"126\" fill=\"#0b0f1a\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">5</text><circle cx=\"130\" cy=\"122\" r=\"11\" fill=\"#6ab08d\"/><text x=\"130\" y=\"126\" fill=\"#0b0f1a\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">6</text><text x=\"170\" y=\"144\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">1手→2手→3手…と、輪を広げるように浅い順に調べる</text></svg>"}'::jsonb),
  ('g-kentei-c-q21', '{"terms": [["局所最適解", "本当の最小ではないが、まわりより低いために止まってしまう地点"], ["大域最適解", "全体の中で本当に一番低い、目指すべき最小の地点"], ["なぜ最小を目指すのか", "学習では「誤差(モデルの予測と正解のズレ)」を測る関数(損失関数)を使う。誤差は小さいほど良い成績なので、これを最小にすることがそのまま『一番良い状態』を目指すことになる。精度を最大化する、という言い方もできるが、計算のしやすさから多くの手法は誤差を最小化するという形にそろえて扱う"]]}'::jsonb),
  ('g-kentei-c-q22', '{"think": "なぜ勾配の大きさが学習の良し悪しを左右するのかがカギ。勾配とは『今の重みをどちらへ・どれだけ動かせば誤差が減るか』を教える合図で、学習はこの合図の通りに重みを少しずつ動かして賢くなっていく。合図の大きさがちょうどよければ、重みは少しずつ正しい方向へ近づく。ところが層を伝わるうちに勾配が掛け算で膨らみ続けると、合図が異常に大きくなることがある。合図が大きすぎると、重みが一歩で遠くまで飛ばされて正しい場所を通り過ぎ、かえって誤差が増えたり、次の合図がさらに大きくなって値が発散したりする(勾配爆発)。これでは学習が安定して進むどころか壊れてしまう。そこで勾配の大きさに上限を設け、それを超えたら一定の大きさまで削って頭打ちにするのが勾配クリッピング。一歩の大きさを暴走させないことで、学習を安定させる。"}'::jsonb),
  ('g-kentei-g-q49', '{"terms": [["チャネル", "画像の「色や特徴の種類」を並べる軸。カラー画像ならR(赤)・G(緑)・B(青)の3チャネルからスタートし、畳み込みが進むにつれて「エッジらしさ」「丸みらしさ」など学習で見つけた特徴の種類がチャネル数として増えていく"], ["空間方向", "画像の「縦×横」の位置を表す軸。同じチャネルの中で、その特徴が上下左右のどこにあるかを表す"], ["MobileNet", "スマートフォンなど非力な端末向けに設計された軽量な画像認識モデル"], ["Depthwise Separable Convolution", "直訳は「深さ方向に分けられる畳み込み」。通常の畳み込みを2段階に分ける工夫"], ["エッジAI", "スマートフォンやセンサーなど、クラウドではなく端末側でAIの計算を行う仕組み"]]}'::jsonb),
  ('g-kentei-j-q9', '{"viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">傾き(接線)の急さがそのまま勾配の縮み方</text><text x=\"80\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">シグモイド（傾きの上限 0.25）</text><line x1=\"30\" y1=\"90\" x2=\"150\" y2=\"90\" stroke=\"#2a2f3f\"/><path d=\"M30 105 C55 105,65 45,90 45 C115 45,125 75,150 75\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/><line x1=\"70\" y1=\"70\" x2=\"105\" y2=\"38\" stroke=\"#c47070\" stroke-width=\"1.6\" stroke-dasharray=\"2,2\"/><text x=\"38\" y=\"58\" fill=\"#c47070\" font-size=\"7.5\">なだらかな接線</text><text x=\"80\" y=\"122\" fill=\"#8892a4\" font-size=\"8\">出力は0〜1</text><text x=\"255\" y=\"32\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">tanh（傾きの上限 1）</text><line x1=\"200\" y1=\"90\" x2=\"320\" y2=\"90\" stroke=\"#2a2f3f\"/><path d=\"M200 115 C220 115,230 20,260 20 C290 20,300 65,320 65\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.8\"/><line x1=\"243\" y1=\"80\" x2=\"270\" y2=\"28\" stroke=\"#6ab08d\" stroke-width=\"1.6\" stroke-dasharray=\"2,2\"/><text x=\"272\" y=\"55\" fill=\"#6ab08d\" font-size=\"7.5\">急な接線</text><text x=\"255\" y=\"122\" fill=\"#8892a4\" font-size=\"8\">出力は-1〜1</text><text x=\"170\" y=\"135\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">接線が急なtanhの方が、掛け算を重ねても値が縮みにくい</text></svg>"}'::jsonb),
  ('g-kentei-q16', '{"terms": [["k分割交差検証", "データをk組に分け、テスト役を交代させながらk回評価して平均する方法"], ["ホールドアウト検証", "データを訓練用とテスト用に一度だけ分けて評価する、シンプルな方法"], ["k（一般に使う記号）", "数学では『好きな数を当てはめてよい一般的な個数』を表すのに n や k という文字をよく使う。ここでのkも『5でも10でも、好きな分割数を当てはめてよい』という意味の置き換え文字で、k=5なら5分割交差検証、k=10なら10分割交差検証と呼ぶ"]]}'::jsonb),
  ('g-kentei-q20', '{"kid": "そもそも「勾配」とは、今いる場所からどちらへ・どれだけ動けば誤差(間違いの大きさ)が一番減るかを教えてくれる矢印のこと。この矢印の向きに沿って重みを動かしていくのが「坂を下る」というたとえの意味。AIの学習は「成績が一番良くなる場所へ、この矢印を頼りに少しずつ坂を下っていく」イメージ。その下り方を賢くするのが最適化で、Adamは「これまで進んできた勢いを活かす工夫（モメンタム）」と「方向ごとに歩幅を自動で変える工夫（RMSProp）」の合わせ技。"}'::jsonb),
  ('g-kentei-q22', '{"viz": "<svg viewBox=\"0 0 340 155\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じ4つの重みが、L1とL2でどう変わるか</text><text x=\"8\" y=\"46\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">元の重み</text><line x1=\"65\" y1=\"48\" x2=\"185\" y2=\"48\" stroke=\"#2a2f3f\"/><rect x=\"70\" y=\"38\" width=\"14\" height=\"10\" fill=\"#5b6577\"/><rect x=\"100\" y=\"20\" width=\"14\" height=\"28\" fill=\"#5b6577\"/><rect x=\"130\" y=\"41\" width=\"14\" height=\"7\" fill=\"#5b6577\"/><rect x=\"160\" y=\"26\" width=\"14\" height=\"22\" fill=\"#5b6577\"/><text x=\"77\" y=\"58\" fill=\"#8892a4\" font-size=\"7\" text-anchor=\"middle\">項目1</text><text x=\"107\" y=\"58\" fill=\"#8892a4\" font-size=\"7\" text-anchor=\"middle\">項目2</text><text x=\"137\" y=\"58\" fill=\"#8892a4\" font-size=\"7\" text-anchor=\"middle\">項目3</text><text x=\"167\" y=\"58\" fill=\"#8892a4\" font-size=\"7\" text-anchor=\"middle\">項目4</text><text x=\"8\" y=\"91\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">L1後</text><line x1=\"65\" y1=\"93\" x2=\"185\" y2=\"93\" stroke=\"#2a2f3f\"/><rect x=\"70\" y=\"91\" width=\"14\" height=\"2\" fill=\"#c47070\"/><text x=\"77\" y=\"86\" fill=\"#c47070\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">0</text><rect x=\"100\" y=\"69\" width=\"14\" height=\"24\" fill=\"#3b82f6\"/><rect x=\"130\" y=\"91\" width=\"14\" height=\"2\" fill=\"#c47070\"/><text x=\"137\" y=\"86\" fill=\"#c47070\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">0</text><rect x=\"160\" y=\"75\" width=\"14\" height=\"18\" fill=\"#3b82f6\"/><text x=\"230\" y=\"82\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">2つがちょうど0になり消える</text><text x=\"230\" y=\"93\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">(効かない項目の選別)</text><text x=\"8\" y=\"136\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">L2後</text><line x1=\"65\" y1=\"138\" x2=\"185\" y2=\"138\" stroke=\"#2a2f3f\"/><rect x=\"70\" y=\"132\" width=\"14\" height=\"6\" fill=\"#60a5fa\" opacity=\"0.85\"/><rect x=\"100\" y=\"118\" width=\"14\" height=\"20\" fill=\"#60a5fa\" opacity=\"0.85\"/><rect x=\"130\" y=\"134\" width=\"14\" height=\"4\" fill=\"#60a5fa\" opacity=\"0.85\"/><rect x=\"160\" y=\"123\" width=\"14\" height=\"15\" fill=\"#60a5fa\" opacity=\"0.85\"/><text x=\"230\" y=\"123\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">4つとも残るが</text><text x=\"230\" y=\"134\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">全部小さいまま(0にならない)</text></svg>", "usecase": "たとえば『家の値段を、部屋数・築年数・駅からの距離・最寄りコンビニの数・郵便番号の下2桁…』のように、効きそうもない項目まで大量に入れてモデルを作ったとする。L1正則化をかけると、学習の途中で『郵便番号の下2桁』のような効かない項目の重みがちょうど0になり、実質そのモデルから消えてくれる。残るのは『本当に効く項目だけ』を使ったシンプルなモデル(これを特徴量選択という)。項目が多すぎて何が効いているか分からないとき、L1正則化にかけるだけで『効く項目の絞り込み』を機械にやらせられるのが実務でのうれしさ。"}'::jsonb),
  ('g-kentei-q24', '{"terms": [["ニューラルネットワーク", "入力を受け取る「入力層」、答えを出す「出力層」、その間で計算する「隠れ層」を、たくさんのノード(ミニ計算機)でつないだ仕組み。各ノードは入力に重み(効き具合のつまみ)を掛けて足し合わせ、活性化関数で変換して次の層へ渡す。この重みを学習データから自動で調整していくことで、複雑なパターンを学べるようになる"], ["畳み込み層", "小さなフィルタを画像全体で使い回し、場所によらず線や角などの局所的な特徴を拾う層"], ["重み共有", "同じフィルタを全体で使い回すことで、覚える数（パラメータ）を少なく抑える仕組み"], ["CNN（Convolutional Neural Network）", "convolution＝畳み込み。小さな窓を画像の上でスライドさせて特徴を拾う。画像認識で標準のニューラルネットワーク"]]}'::jsonb),
  ('g-kentei-q3', '{"usecase": "今のChatGPTなどの生成AIは、会話が自然でまるで理解しているように見えるが、サールの整理では『理解しているフリが上手な道具（弱いAI）』にすぎない。この線引きを知っておくと、AIの出力を『人格を持つ何か』のように過大評価して丸ごと信じてしまう失敗を避けられる。逆に『AIには本物の心があるのか』という強いAIの論争は、AIの権利や責任の所在といった今のAIガバナンス論議にもつながる、実務にも効いてくる区別。"}'::jsonb),
  ('g-kentei-q8', '{"viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arr8\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#c47070\"/></marker></defs><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">一本道をとことん深く、行き止まったら戻る</text><circle cx=\"140\" cy=\"35\" r=\"11\" fill=\"#3b82f6\"/><text x=\"140\" y=\"39\" fill=\"#0b0f1a\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">1</text><line x1=\"140\" y1=\"46\" x2=\"140\" y2=\"63\" stroke=\"#8892a4\"/><circle cx=\"140\" cy=\"74\" r=\"11\" fill=\"#60a5fa\"/><text x=\"140\" y=\"78\" fill=\"#0b0f1a\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">2</text><line x1=\"140\" y1=\"85\" x2=\"140\" y2=\"102\" stroke=\"#8892a4\"/><circle cx=\"140\" cy=\"113\" r=\"11\" fill=\"#60a5fa\"/><text x=\"140\" y=\"117\" fill=\"#0b0f1a\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">3</text><text x=\"140\" y=\"135\" fill=\"#c47070\" font-size=\"8\" text-anchor=\"middle\">行き止まり</text><line x1=\"151\" y1=\"74\" x2=\"197\" y2=\"59\" stroke=\"#8892a4\"/><circle cx=\"210\" cy=\"55\" r=\"11\" fill=\"#6ab08d\"/><text x=\"210\" y=\"59\" fill=\"#0b0f1a\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">4</text><text x=\"262\" y=\"59\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">1つ戻り別の枝へ</text><path d=\"M140 106 C168 92, 188 74, 200 63\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.3\" stroke-dasharray=\"2,2\" marker-end=\"url(#arr8)\"/></svg>"}'::jsonb)
) AS v(source_ref, patch)
WHERE q.source_ref = v.source_ref
  AND q.subject_id IN (SELECT id FROM public.subjects WHERE slug LIKE 'g-kentei%');

